def get_perimeter(r):
    cells = []
    for x in range(-r, r + 1):
        for y in range(-(r - abs(x)), (r - abs(x)) + 1):
            cells.append((x, y))

    perimeter = 0
    for x, y in cells:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if abs(nx) + abs(ny) > r:
