def simulate_with_walls(initial_cells, gamma):
    cells = set(initial_cells)
    walls = set()
    history = []
    for n in range(1, 21):
        potential_cells = {}
        for x, y in cells:
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if (nx, ny) not in cells:
                    potential_cells[(nx, ny)] = potential_cells.get((nx, ny), 0) + 1

        k1_cells = [c for c, k in potential_cells.items() if k == 1]
        k1_cells.sort()

        num_k1_to_block = min(len(k1_cells), gamma)
        for i in range(num_k1_to_block):
            c = k1_cells[i]
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = c[0] + dx, c[1] + dy
                if (nx, ny) in cells:
                    walls.add((c[0], c[1], nx, ny))
                    walls.add((nx, ny, c[0], c[1]))
                    break

        new_cells = set()
        for x, y in cells:
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if (nx, ny) not in cells:
                    if (x, y, nx, ny) not in walls and (nx, ny, x, y) not in walls:
                        new_cells.add((nx, ny))
        cells = cells | new_cells
        history.append(get_perimeter(cells))
    return history

